/**
 * A penugem da coruja — duas ondas que se somam, e o ruído que sobra.
 *
 * A franja da asa da coruja quebra o ar em correntes que chegam DEFASADAS ao
 * mesmo ponto. Somadas, elas se cancelam: é por isso que a coruja voa sem fazer
 * barulho. A cena mostra as três coisas empilhadas — a onda de cima, a de baixo
 * defasada, e a soma — porque o que interessa não é nenhuma das duas, é o que
 * resta quando elas se encontram.
 *
 * As ondas correm com o tempo, e não com o slider: o slider muda só a DEFASAGEM
 * entre elas. Parar a animação faria parecer que a defasagem é a posição.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** Ciclos visíveis na largura do quadro. */
const CICLOS = 2.5;

const ondas: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const fase = numeroDe(valores, 'fase', 0);
    const ruido = numeroDe(info, 'ruido', 100);
    const ok = info.ok === true;
    const tinta = ok ? cor.verde : cor.azul;

    const rad = (fase * Math.PI) / 180;

    titulo(ctx, L, A, 'Em oposição de fase, as ondas se cancelam');

    // A margem esquerda é larga porque o rótulo de B carrega a defasagem.
    const x0 = L * 0.16;
    const x1 = L * 0.78;
    const largura = x1 - x0;
    const miudo = limitar(A * 0.03, 8, 11);

    /** Uma faixa: rótulo à esquerda, onda dentro. */
    const faixa = (
      centro: number,
      altura: number,
      rotulo: string,
      corLinha: string,
      espessura: number,
      onda: (u: number) => number,
      tracejada: boolean,
    ): void => {
      ctx.strokeStyle = cor.trilho;
      ctx.lineWidth = 1;
      ctx.setLineDash([2, 4]);
      ctx.beginPath();
      ctx.moveTo(x0, centro);
      ctx.lineTo(x1, centro);
      ctx.stroke();
      ctx.setLineDash([]);

      ctx.strokeStyle = corLinha;
      ctx.lineWidth = espessura;
      ctx.lineJoin = 'round';
      if (tracejada) ctx.setLineDash([6, 4]);
      ctx.beginPath();
      for (let i = 0; i <= 160; i++) {
        const u = i / 160;
        const px = x0 + u * largura;
        const py = centro - onda(u) * altura;
        if (i === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.stroke();
      ctx.setLineDash([]);

      texto(ctx, rotulo, x0 - 4, centro, miudo, {
        cor: cor.fraco,
        peso: 700,
        alinhamento: 'right',
      });
    };

    const angulo = (u: number): number => u * CICLOS * 2 * Math.PI - t * 2.2;
    const alturaFaixa = A * 0.1;

    // A defasagem vai no rótulo de B, que é de quem ela é. Solta no rodapé da
    // cena ela caía em cima da própria onda-soma, que é a mais alta das três.
    faixa(A * 0.28, alturaFaixa, 'A', cor.azulClaro, 2, (u) => Math.sin(angulo(u)), false);
    faixa(
      A * 0.48,
      alturaFaixa,
      `B +${Math.round(fase)}°`,
      cor.ouro,
      2,
      (u) => Math.sin(angulo(u) + rad),
      true,
    );

    // A soma, com a área sob a curva preenchida: é o "quanto sobra".
    const somaCentro = A * 0.7;
    const soma = (u: number): number => (Math.sin(angulo(u)) + Math.sin(angulo(u) + rad)) / 2;

    ctx.save();
    ctx.fillStyle = ok ? 'rgb(47 143 92 / 18%)' : 'rgb(60 74 158 / 14%)';
    ctx.beginPath();
    ctx.moveTo(x0, somaCentro);
    for (let i = 0; i <= 160; i++) {
      const u = i / 160;
      ctx.lineTo(x0 + u * largura, somaCentro - soma(u) * alturaFaixa * 2);
    }
    ctx.lineTo(x1, somaCentro);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    faixa(somaCentro, alturaFaixa * 2, 'A + B', tinta, 3, soma, false);

    // ── O medidor de ruído, na coluna da direita ─────────────────────────
    const mx = L * 0.86;
    const larguraMedidor = L * 0.075;
    const topo = A * 0.22;
    const alturaMedidor = A * 0.52;
    const preenchido = limitar(ruido / 100, 0, 1) * alturaMedidor;

    retangulo(
      ctx,
      mx - larguraMedidor / 2,
      topo,
      larguraMedidor,
      alturaMedidor,
      larguraMedidor / 2,
      cor.palha,
      cor.trilho,
      1,
    );
    retangulo(
      ctx,
      mx - larguraMedidor / 2,
      topo + alturaMedidor - preenchido,
      larguraMedidor,
      preenchido,
      larguraMedidor / 2,
      ok ? cor.verde : ruido > 50 ? cor.erro : cor.ouro,
    );

    texto(ctx, 'ruído', mx, topo - miudo * 1.2, miudo, { cor: cor.fraco, peso: 700 });
    texto(ctx, `${Math.round(ruido)}%`, mx, topo + alturaMedidor + miudo * 1.4, miudo, {
      cor: ok ? cor.verde : cor.fraco,
      peso: 800,
    });

    rodape(
      ctx,
      L,
      A,
      ok,
      'Silêncio: as ondas se anulam ✔',
      fase < 180
        ? 'As ondas ainda se reforçam — aumente a defasagem.'
        : 'Passou da oposição — volte na direção dos 180°.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default ondas;
